package org.joda.time;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Locale;
import org.joda.time.DateTimeFieldType;
import org.joda.time.base.AbstractPartial;
import org.joda.time.field.AbstractPartialFieldProperty;
import org.joda.time.field.FieldUtils;
import org.joda.time.format.DateTimeFormat;
import org.joda.time.format.DateTimeFormatter;
import org.joda.time.format.ISODateTimeFormat;
import org.joda.time.impl.DateTimeTypes;
import org.joda.time.impl.DateTimeZoneImplementations;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;

public class Partial_Partial_TriageGen0Test {

    @Test
    public void testConstructor_NullTypes() {
        try {
            new Partial(null, new int[]{1}, DateTimeZoneImplementations.UTC);
        } catch (IllegalArgumentException e) {
            assertEquals("Types array must not be null", e.getMessage());
        }
    }

    @Test
    public void testConstructor_NullValues() {
        DateTimeFieldType[] types = {DateTimeTypes.yearOfPeriod()};
        try {
            new Partial(types, null, DateTimeZoneImplementations.UTC);
        } catch (IllegalArgumentException e) {
            assertEquals("Values array must not be null", e.getMessage());
        }
    }

    @Test
    public void testConstructor_MismatchedLengths() {
        DateTimeFieldType[] types = {DateTimeTypes.yearOfPeriod(), DateTimeTypes.monthOfYear()};
        int[] values = {2023};
        try {
            new Partial(types, values, DateTimeZoneImplementations.UTC);
        } catch (IllegalArgumentException e) {
            assertEquals("Values array must be the same length as the types array", e.getMessage());
        }
    }

    @Test
    public void testConstructor_EmptyArrays() {
        DateTimeFieldType[] types = new DateTimeFieldType[0];
        int[] values = new int[0];
        Partial partial = new Partial(types, values, DateTimeZoneImplementations.UTC);
        assertEquals(0, partial.size());
        assertArrayEquals(types, partial.getFieldTypes());
        assertArrayEquals(values, partial.getValues());
    }

    @Test
    public void testConstructor_NullInTypesArray() {
        DateTimeFieldType[] types = {DateTimeTypes.yearOfPeriod(), null};
        int[] values = {2023, 1};
        try {
            new Partial(types, values, DateTimeZoneImplementations.UTC);
        } catch (IllegalArgumentException e) {
            assertEquals("Types array must not contain null: index 1", e.getMessage());
        }
    }

    @Test
    public void testConstructor_ValidOrder() {
        DateTimeFieldType[] types = {DateTimeTypes.yearOfPeriod(), DateTimeTypes.monthOfYear(), DateTimeTypes.dayOfMonth()};
        int[] values = {2023, 10, 25};
        Partial partial = new Partial(types, values, DateTimeZoneImplementations.UTC);
        assertEquals(3, partial.size());
        assertArrayEquals(types, partial.getFieldTypes());
        assertArrayEquals(values, partial.getValues());
    }

    @Test
    public void testConstructor_WrongOrder_SmallestToLargest() {
        // Month is smaller than Year in duration field hierarchy (usually)
        // However, the logic checks compare < 0 (if last < loop, throw error)
        // The error message says "must be in order largest-smallest"
        DateTimeFieldType[] types = {DateTimeTypes.monthOfYear(), DateTimeTypes.yearOfPeriod()};
        int[] values = {10, 2023};
        try {
            new Partial(types, values, DateTimeZoneImplementations.UTC);
        } catch (IllegalArgumentException e) {
            // Depending on Joda implementation of compareTo for DurationFields
            // If month < year, it throws.
            assert(e.getMessage().contains("Types array must be in order largest-smallest"));
        }
    }

    @Test
    public void testConstructor_DuplicateTypes_NoRange() {
        // Mocking behavior where range is null
        DateTimeFieldType type = DateTimeTypes.yearOfPeriod();
        DateTimeFieldType[] types = {type, type};
        int[] values = {2023, 2024};
        try {
            new Partial(types, values, DateTimeZoneImplementations.UTC);
        } catch (IllegalArgumentException e) {
            assert(e.getMessage().contains("Types array must not contain duplicate"));
        }
    }

    @Test
    public void testConstructor_DuplicateTypes_WithRange_FailOnDifferentRangeOrder() {
        // This tests the complex branch involving getRangeDurationType
        // Since we cannot easily mock DateTimeFieldType without a lot of boilerplate,
        // we rely on the logic provided in the snippet.
        // We assume standard Joda types will trigger the duplicate or order check.
        DateTimeFieldType type1 = DateTimeTypes.yearOfPeriod();
        DateTimeFieldType type2 = DateTimeTypes.yearOfPeriod(); 
        DateTimeFieldType[] types = {type1, type2};
        int[] values = {2023, 2024};
        try {
            new Partial(types, values, DateTimeZoneImplementations.UTC);
        } catch (IllegalArgumentException e) {
            // Likely "Types array must not contain duplicate"
        }
    }

    @Test
    public void testConstructor_ValidationFailure() {
        // Use an invalid value for the chronology (e.g., month 13)
        DateTimeFieldType[] types = {DateTimeTypes.yearOfPeriod(), DateTimeTypes.monthOfYear()};
        int[] values = {2023, 13};
        try {
            new Partial(types, values, DateTimeZoneImplementations.UTC);
        } catch (IllegalArgumentException e) {
            // chronology.validate(this, values) will throw if values are invalid
        }
    }

    @Test
    public void testConstructor_ValidationFailure_DayOfMonth() {
        DateTimeFieldType[] types = {DateTimeTypes.yearOfPeriod(), DateTimeTypes.monthOfYear(), DateTimeTypes.dayOfMonth()};
        int[] values = {2023, 2, 30}; // Feb 30 is invalid
        try {
            new Partial(types, values, DateTimeZoneImplementations.UTC);
        } catch (IllegalArgumentException e) {
            // Expected
        }
    }
}
